pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller and a timestamp delta to ensure block timestamp increases
    function testFuzz_property(address caller, uint64 timeDelta) public {
        // keep caller non-zero address (EOA) to be admissible
        vm.assume(caller != address(0));
        // bound timeDelta to a reasonable range to advance timestamp
        uint64 d = bound(timeDelta, 1, 1000);

        // fund the caller so it can send ETH
        vm.deal(caller, 20 ether);

        // set a pastBlockTime in the contract to some earlier time by making an initial call with 10 ether
        // warp forward to ensure block.timestamp increases on the next call
        vm.warp(block.timestamp + 1);

        // perform an initial successful call to set pastBlockTime to current timestamp
        vm.prank(caller);
        c.f{value: 10 ether}();

        // record the pastBlockTime after the successful initial call
        uint256 before = c.pastBlockTime();

        // warp forward by d to ensure next call has a strictly greater timestamp
        vm.warp(block.timestamp + d);

        // Now attempt the decision call: calling fallback with exactly 10 ether
        // The reference contract accepts msg.value == 10 ether; the mutant requires 11 and will revert
        bool ok;
        vm.prank(caller);
        try c.f{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for ANY admissible inputs the reference accepts a call with 10 ether
        // and thus updates pastBlockTime to a strictly greater value than before. We assert that
        // the call succeeded (ok == true) and that pastBlockTime increased.
        // This single assertTrue reads c's public getter to confirm behavior.
        assertTrue(ok && c.pastBlockTime() > before);
    }
}

