contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the caller address and a future timestamp delta to ensure block.timestamp > pastBlockTime
    function testFuzz_property(address caller, uint256 timeDelta) public {
        // keep timeDelta in a reasonable wide range but non-zero so timestamp advances
        uint256 dt = bound(timeDelta, 1, 10000);

        // ensure caller is a useful EOA by giving it some balance
        vm.deal(caller, 20 ether);

        // ensure stored pastBlockTime is less than current timestamp by warping backwards, if needed
        // read current stored pastBlockTime
        uint256 before = c.pastBlockTime();

        // warp forward so block.timestamp > pastBlockTime
        // choose new timestamp at least 1..dt seconds ahead of before and current block
        uint256 target = before + dt;
        if (target <= block.timestamp) {
            // if target not ahead of current, set to block.timestamp + dt
            target = block.timestamp + dt;
        }
        vm.warp(target);

        // Now call fallback with exactly 10 ether from the fuzzed caller.
        bool ok;
        vm.prank(caller);
        try c.call{value: 10 ether}("") {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract accepts (does not revert) any fallback call with msg.value == 10 ether when
        // block.timestamp > pastBlockTime. The mutant requiring 11 ether will revert for such a call.
        assertTrue(ok);
    }
