pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: caller address and a timestamp to set/warp to
    function testFuzz_property(address caller, uint256 ts) public {
        // keep caller non-zero
        vm.assume(caller != address(0));

        // We will fuzz a timestamp; constrain it to reasonable block timestamp range
        uint256 warpTs = bound(ts, 1, type(uint256).max / 2);

        // Give caller some funds so it can send 10 ether
        vm.deal(caller, 20 ether);

        // 1) Ensure contract has some balance so transfers (on multiples of 15 blocks) have effect if triggered
        // fund contract from this test contract
        payable(address(c)).transfer(1 ether);

        // 2) Set the stored pastBlockTime to warpTs (simulate prior call happened at warpTs)
        // To set pastBlockTime to warpTs, we warp and do a call that sends exactly 10 ether and respects ordering.
        // warp to warpTs - 1 so that next call at warpTs will be > pastBlockTime (if needed)
        vm.warp(warpTs - 1);
        // perform a first call from this contract to set pastBlockTime to current timestamp = warpTs -1
        // but fallback requires msg.value == 10 ether, so use a separate prank as caller to send 10 ether
        vm.deal(caller, 20 ether);
        vm.prank(caller);
        c.f{value: 10 ether}();

        // Now pastBlockTime is warpTs -1. We want to create a situation where block.timestamp == pastBlockTime
        // by warping to warpTs -1 and calling again. That will be equal, not greater.
        vm.warp(warpTs - 1);

        // Now perform the decisive call at the SAME timestamp as stored pastBlockTime.
        // The general rule: reference requires block.timestamp > pastBlockTime, so at equal timestamp it must NOT update.
        // The mutant (without the check) WILL update pastBlockTime to the same value (no visible change in value but the act of update is observable because the reference will not perform the assignment when equal).
        // To observe the difference we rely on the fact that reference will not modify pastBlockTime when timestamp is not greater.

        // Capture value before the decisive call
        uint256 before = c.pastBlockTime();

        // Make the call: caller sends exactly 10 ether to trigger fallback
        vm.prank(caller);
        c.f{value: 10 ether}();

        // Capture value after the decisive call
        uint256 after = c.pastBlockTime();

        // The universal property: for ALL inputs where the call sends 10 ether at a block.timestamp equal to stored pastBlockTime,
        // reference C must NOT change pastBlockTime (after == before). The mutant (without the timestamp check) will perform the assignment
        // and may change behavior; the fuzzer can find such inputs where mutant differs. We assert the property on the reference.
        assertTrue(after == before);
    }
}

