pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: actor address and an initial timestamp delta to advance time
    function testFuzz_property(address actor, uint64 warpDelta) public {
        // Keep actor non-zero and warpDelta in a wide but sensible range
        vm.assume(actor != address(0));
        // bound warpDelta to avoid overflow in vm.warp for extremely large values
        uint64 d = uint64(bound(uint256(warpDelta), 1, 1 days));

        // Deploy a helper that accepts transfers (so payable transfer succeeds)
        AcceptingReceiver recv = new AcceptingReceiver();

        // Fund the actor so they can send 10 ether
        vm.deal(actor, 20 ether);

        // ensure block.timestamp > pastBlockTime: set pastBlockTime to now - 1
        // first call to fallback must observe block.timestamp > pastBlockTime
        vm.warp(block.timestamp); // normalize

        // set caller to our receiver so that when C.transfer(payable(msg.sender)) happens
        // the transfer will succeed (this is the adversarial cooperative caller)
        // but we still fuzz the external actor that originates the tx; we'll use actor as the tx origin

        // set the contract's pastBlockTime to an earlier time by making an initial call via a different actor
        // Perform an initial call to set pastBlockTime to current timestamp - 2 (simulate prior state)
        // We cannot directly set pastBlockTime, so call once from actor to advance it, then warp back
        vm.prank(actor);
        c.f{value: 10 ether}();

        // warp back in time to create a situation where next call sees block.timestamp > pastBlockTime
        // (increase time forward by d so that block.timestamp > pastBlockTime holds)
        vm.warp(block.timestamp + d);

        // Now, make the fallback call originate from the AcceptingReceiver but with tx.origin = actor.
        // Since fuzzed address actor cannot be a contract with code, we simulate the scenario by having
        // the actor externally call the receiver which forwards to c, preserving msg.sender as receiver
        // and tx.origin as actor. To do this, fund the receiver and have the actor call its forward function.
        vm.deal(address(recv), 0);

        // actor will call recv.forward{value: 10 ether}(address(c)) which will call c.fallback
        vm.prank(actor);
        // forward from recv to c, so in c's fallback, msg.sender == recv (a contract that accepts transfer)
        recv.forward{value: 10 ether}(address(c));

        // After the call completes, the reference C always updated pastBlockTime to current block.timestamp
        // Read the public getter pastBlockTime and assert it's equal to block.timestamp
        // This is the single assertion required.
        assertTrue(c.pastBlockTime() == block.timestamp);
    }
}

// minimal helper: accepts transfers and can forward calls to C preserving msg.sender as the helper
contract AcceptingReceiver {
    receive() external payable {}

    // forward call to target C via low-level call so that target.fallback() is invoked with msg.sender = this
    function forward(address target) external payable {
        // forward all gas and value
        (bool ok, ) = target.call{value: msg.value}("");
        require(ok, "forward failed");
    }
}

