import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz: caller address and a block number offset to hit the conditional; block.timestamp is controlled via vm.warp
    function testFuzz_property(address caller, uint256 blockOffset) public {
        // Keep caller as a contract that will accept transfers. We cannot use arbitrary address (EOA won't have code).
        vm.assume(caller != address(0));

        // Deploy a minimal accepting helper and use its address as the caller if the fuzzed address is not a contract.
        // But we still fuzz another value: blockOffset to vary block.number so that (block.number % 15 == 0) sometimes holds.
        AcceptingCaller ac = new AcceptingCaller();
        address payable ad = payable(address(ac));

        // choose a block number such that we can reach both branches; bound keeps wide
        uint256 targetBlock = bound(blockOffset, 0, 1000) + 1; // avoid block 0
        vm.roll(targetBlock);

        // ensure timestamp increases relative to stored pastBlockTime (initial 0)
        uint256 ts = block.timestamp + 1;
        vm.warp(ts);

        // fund the caller so it can receive (not strictly necessary for transfer, but safe)
        vm.deal(ad, 1 ether);

        // ensure the contract has no balance to start with (setUp freshly deployed), but fallback requires msg.value == 10 ether
        // make the call from the accepting contract address
        vm.prank(ad);
        // call fallback with exactly 10 ether
        (bool ok, ) = address(c).call{value: 10 ether}("");

        // After call, reference C always sets pastBlockTime == block.timestamp when call succeeded and initial require conditions met.
        // We assert that when the call succeeded, c.pastBlockTime() == block.timestamp.
        // This property holds for the reference; the mutant can violate it when it transfers out before updating the timestamp.
        if (ok) {
            assertTrue(c.pastBlockTime() == block.timestamp);
        } else {
            // if call reverted, then the preconditions weren't met; for the reference contract the revert means property about state update doesn't apply.
            // We still assert that pastBlockTime is <= block.timestamp (initial 0 or previously set), a weak invariant the reference always holds.
            assertTrue(c.pastBlockTime() <= block.timestamp);
        }
    }
}

