pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address and a timestamp jump to ensure block.timestamp > pastBlockTime
    function testFuzz_property(address caller, uint256 timeAdvance) public {
        // keep caller non-zero
        vm.assume(caller != address(0));
        // keep timeAdvance reasonable but wide to let fuzzer explore
        timeAdvance = bound(timeAdvance, 1, 1 days);

        // deploy a helper that will revert when receiving Ether
        Reverter rev = new Reverter();

        // fund the revoker so it can be the caller EOA in vm.prank
        vm.deal(address(rev), 0);

        // ensure c has some balance so a transfer would have funds to send
        // top up contract by sending 10 ether first from some funded address
        address funder = address(0xABCD);
        vm.deal(funder, 20 ether);
        vm.prank(funder);
        // send 10 ether to contract via fallback
        (bool sent, ) = address(c).call{value: 10 ether}("");
        require(sent, "fund send failed");

        // advance time so block.timestamp > pastBlockTime (pastBlockTime initially 0)
        vm.warp(block.timestamp + timeAdvance);

        // now have the reverter contract be the caller: it has a fallback that will revert when receiving
        // but we need the external caller to be an EOA that triggers c.fallback and then c might transfer back
        // so we use vm.prank with the address of the reverter contract (as the msg.sender)
        // ensure the caller has some balance to send 10 ether
        vm.deal(address(rev), 10 ether);

        // perform the call: reverter contract address as msg.sender
        vm.prank(address(rev));
        bool ok;
        // try/catch to observe whether the call reverts; we only care about post-state via getter
        try c.f{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: after this interaction with a reverting recipient, the correct
        // contract C must have pastBlockTime equal to block.timestamp (i.e., updated). We read via the public getter.
        // (The mutant can fail to update pastBlockTime for some inputs where it transfers before updating state.)
        uint pb = c.pastBlockTime();
        // exactly one assertion as required
        assertTrue(pb == block.timestamp, "pastBlockTime not updated to current timestamp");
    }
}

contract Reverter {
    // revert on any receive or fallback when sent Ether
    receive() external payable { revert("no accept"); }
    fallback() external payable { revert("no accept"); }
}

