pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: a caller address and a block number to decide whether transfer should have drained
    function testFuzz_property(address caller, uint256 targetBlock) public {
        // keep caller non-zero
        vm.assume(caller != address(0));
        // restrict block number to a reasonable future range to avoid VM limits
        uint256 b = bound(targetBlock, 1, type(uint256).max - 1);

        // ensure we are at block 1 initially
        vm.roll(1);
        // fund caller so it can send 10 ether
        vm.deal(caller, 20 ether);

        // advance to target block and ensure timestamp strictly increases
        // set block number to b and timestamp to b (monotonic)
        vm.roll(b);
        vm.warp(uint256(block.timestamp) + 1);

        // perform the payable fallback call from the fuzzed caller
        vm.prank(caller);
        c.f{value: 10 ether}();

        // After the call: the reference drains if and only if block.number % 15 == 0
        // We observe c's balance (public observable). This single assertion is the universal property.
        bool shouldDrain = (block.number % 15 == 0);
        // If drained, balance == 0; otherwise balance == 10 ether (since constructor didn't fund it and we sent 10)
        uint256 expected = shouldDrain ? 0 : 10 ether;
        assertTrue(address(c).balance == expected);
    }
}

