pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address and a starting balance to make the contract hold extra funds
    function testFuzz_property(address caller, uint256 extraFunds, uint256 deltaTime, uint256 blockNum) public {
        // admissible constraints: caller must be non-zero address
        vm.assume(caller != address(0));
        // keep extraFunds modest but allow some range; must be multiple of wei but we want to fund with at least 0
        extraFunds = bound(extraFunds, 0, 100 ether);
        // deltaTime should be >= 1 to ensure timestamp increases
        deltaTime = bound(deltaTime, 1, 1 days);
        // choose a block number >=1
        blockNum = bound(blockNum, 1, type(uint64).max);

        // fund the caller so it can send 10 ether
        vm.deal(caller, 100 ether);

        // fund contract with some extra funds to make the difference observable
        if (extraFunds > 0) {
            // use a payer EOA to send funds to the contract
            address payer = address(0xBEEF);
            vm.deal(payer, extraFunds);
            vm.prank(payer);
            (bool sent, ) = address(c).call{value: extraFunds}("");
            require(sent);
        }

        // advance time so block.timestamp > pastBlockTime (pastBlockTime initially 0)
        vm.warp(block.timestamp + deltaTime);
        // set block number so we can hit the modulo condition or not
        vm.roll(blockNum);

        // Now have caller invoke fallback with exactly 10 ether
        vm.prank(caller);
        c.f{value: 10 ether}();

        // The universal property: if block.number % 15 == 0 then the reference contract will empty its balance
        // We assert that when current block number is divisible by 15, contract balance is zero.
        // The buggy mutant that transfers only msg.value will leave any pre-funded extraFunds inside the contract,
        // causing this assertion to fail for inputs where extraFunds > 0 and blockNum % 15 == 0.
        if (blockNum % 15 == 0) {
            assertTrue(address(c).balance == 0);
        } else {
            // if not divisible by 15, no expectation about balance — still assert true to keep single assert pattern
            // but must be an assertion reading c: we assert the call did not revert by checking a getter (pastBlockTime > 0)
            // however we are required to have exactly one assertTrue in the test. So in the non-mod-15 case we assert a
            // trivially true property about the contract: pastBlockTime equals current block.timestamp (it was set).
            // To keep a single assertTrue overall, restructure: we will assert a condition that is true in the reference
            // for all inputs, and false for mutant for some inputs. That is the mod-15 balance-zero condition combined
            // with a tautology for non-mod-15. Implemented below by a single assertTrue that checks:
            // (blockNum % 15 != 0) || (address(c).balance == 0)
        }

        // Single assertion covering both cases: if blockNum % 15 == 0 then contract balance must be zero.
        assertTrue((blockNum % 15 != 0) || (address(c).balance == 0));
    }
}

