pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: initialBalance (wei) seeded into C, and an arbitrary sender address
    function testFuzz_property(uint256 initialBalance, address sender) public {
        // Keep domains reasonable
        // initialBalance must be large enough so that sending 10 ether is meaningful
        // bound initialBalance to [0, 100 ether]
        initialBalance = bound(initialBalance, 0, 100 ether);
        // avoid zero-address sender
        vm.assume(sender != address(0));

        // Deploy a helper that will revert when receiving exactly 10 ether but accept other amounts
        ReverterReceiver bad = new ReverterReceiver();

        // Fund the contract c with initialBalance so the reference's transfer of entire balance has effect
        if (initialBalance > 0) {
            vm.deal(address(this), initialBalance);
            // send initialBalance to c from this contract
            (bool okInit, ) = address(c).call{value: initialBalance}("");
            require(okInit);
        }

        // Ensure block.timestamp increases relative to pastBlockTime (which is initially 0)
        vm.warp(block.timestamp + 1);

        // Warp to a block number that is multiple of 15, so the branch triggers
        uint256 targetBlock = block.number;
        // find next multiple of 15 >= current
        uint256 rem = targetBlock % 15;
        if (rem != 0) {
            targetBlock += (15 - rem);
        }
        vm.roll(targetBlock);

        // Fund the adversarial sender and call fallback with exactly 10 ether from that contract
        vm.deal(address(bad), 20 ether);
        // We will invoke c.fallback by making bad call c with 10 ether from bad contract
        // The distinguishing behavior: the reference forwards entire balance to bad (an external call),
        // whereas the mutant would forward only msg.value. bad.recentlyReverted toggles behavior based on amount received.

        // Call c.fallback from the adversarial contract (bad) with 10 ether value
        bool ok;
        try bad.callFallback{value: 10 ether}(address(c)) {
            ok = true;
        } catch {
            ok = false;
        }

        // The single assertion: for this adversarial callee and the chosen block conditions, the reference
        // contract will NOT accept a receive that reverts on receiving exactly msg.value while accepting larger amounts.
        // We assert that the call did NOT succeed. The reference will succeed (since it forwards entire balance and bad only reverts on receiving exactly 10 ether),
        // but the mutant that forwards only msg.value would cause bad to revert — therefore, there exist inputs where the mutant fails and reference passes.
        // Here we assert the observed outcome is `ok == false`, which the mutant produces for some inputs while the reference does not.

        // NOTE: The property we assert must hold for the reference for ALL admissible inputs. We crafted the scenario so the reference passes
        // (sends entire balance) and thus the call should succeed; the mutant can fail. However, the test harness runs against the reference C,
        // so to make this test pass on the reference for all admissible inputs, we assert the opposite: that the call succeeded (ok == true).
        // The instruction requires the single assertTrue is a property the reference satisfies always and the mutant breaks for some input.
        // So we assert the call succeeded.

        assertTrue(ok);
    }
}

// Adversarial helper that reverts when it receives exactly 10 ether, but accepts other amounts.
contract ReverterReceiver {
    // allow this contract to be sent arbitrary funds
    receive() external payable {
        // revert if exactly 10 ether is received
        if (msg.value == 10 ether) {
            revert("reject ten");
        }
        // otherwise accept
    }

    // helper to call fallback on target
    function callFallback(address target) external payable {
        // call target's fallback with the provided msg.value
        (bool ok, ) = target.call{value: msg.value}("");
        require(ok);
    }
}

