    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: caller address and a timestamp to warp to
    function testFuzz_property(address caller, uint256 ts) public {
        // Keep caller non-zero to be a valid EOA
        vm.assume(caller != address(0));
        // bound timestamp to a reasonable future range to avoid underflow in comparisons
        ts = bound(ts, 1, type(uint64).max);

        // Ensure caller has ETH to send
        vm.deal(caller, 20 ether);

        // Advance block timestamp to 'ts' and ensure it's > initial pastBlockTime (which is 0)
        vm.warp(ts);

        // Make the call from caller sending exactly 10 ether as required by the contract
        vm.prank(caller);
        c.f{value: 10 ether}();

        // General rule: after a successful call that passed the require(block.timestamp > pastBlockTime),
